from temporalio import workflow, activity
from datetime import timedelta


@activity.defn
async def extract(pdf_url: str) -> dict:
    return {'text': '...'}


@activity.defn
async def summarize(text: str) -> str:
    return 'resumen'


@workflow.defn
class ReportFlow:
    @workflow.run
    async def run(self, pdf_url: str) -> str:
        # Cada execute_activity se vuelve un paso persistido por Temporal;
        # si el worker cae a mitad, el workflow se reanuda desde el punto de falla
        # sin repetir la actividad ya concluida.
        extracted = await workflow.execute_activity(
            extract,
            pdf_url,
            start_to_close_timeout=timedelta(minutes=2),
        )
        return await workflow.execute_activity(
            summarize,
            extracted['text'],
            start_to_close_timeout=timedelta(minutes=2),
        )

