import { StateGraph, END } from '@langchain/langgraph';

type S = { messages: any[]; stage: 'pending' | 'researched' | 'written' };

async function orchestrator(s: S) {
  if (s.stage === 'pending')  return 'researcher';
  if (s.stage === 'researched') return 'writer';
  return END;
}

const graph = new StateGraph<S>({ channels: { messages: [], stage: 'pending' } })
  .addNode('orchestrator', orchestrator)
  .addNode('researcher',  async (s) => ({ ...s, stage: 'researched' as const }))
  .addNode('writer',      async (s) => ({ ...s, stage: 'written' as const }))
  .addEdge('__start__', 'orchestrator')
  .addConditionalEdges('orchestrator', (s) => s.stage,
    { researcher: 'researcher', writer: 'writer', written: END, [END]: END })
  .addEdge('researcher', 'orchestrator')
  .addEdge('writer',     'orchestrator')
  .compile({ checkpointer: redisCheckpointer });
